from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        # Coordinate compression
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)

        cnt = [0] * (m + 2)
        sm = [0] * (m + 2)

        # Largest power of 2 <= m for binary lifting on Fenwick tree
        LOG = 1
        while LOG * 2 <= m:
            LOG *= 2

        costs = []
        total_sum = 0
        mid_pos = (x + 1) // 2  # 1-indexed median position

        for i in range(n):
            # Inline update for adding nums[i]
            idx = rank[nums[i]]
            val = nums[i]
            while idx <= m:
                cnt[idx] += 1
                sm[idx] += val
                idx += idx & -idx
            total_sum += val

            if i >= x:
                # Inline update for removing nums[i - x]
                idx = rank[nums[i - x]]
                val = nums[i - x]
                while idx <= m:
                    cnt[idx] -= 1
                    sm[idx] -= val
                    idx += idx & -idx
                total_sum -= val

            if i >= x - 1:
                # Inline find_kth to locate the median's rank
                idx = 0
                bit = LOG
                remaining = mid_pos
                while bit > 0:
                    nxt = idx + bit
                    if nxt <= m and cnt[nxt] < remaining:
                        idx = nxt
                        remaining -= cnt[nxt]
                    bit //= 2
                mr = idx + 1

                # Inline combined queries for strictly smaller elements
                idx = mr - 1
                lower_sum = 0
                lower_cnt = 0
                while idx > 0:
                    lower_sum += sm[idx]
                    lower_cnt += cnt[idx]
                    idx -= idx & -idx

                median = vals[mr - 1]
                # Calculate the minimal operations for the current sliding window
                cost = (median * lower_cnt - lower_sum 
                        + (total_sum - lower_sum) - median * (x - lower_cnt))
                costs.append(cost)

        # DP
        INF = float('inf')
        dp = [[0] + [INF] * k for _ in range(n + 1)]

        for p in range(1, n + 1):
            dp_p = dp[p]
            dp_p_minus_1 = dp[p - 1]
            if p < x:
                for j in range(1, k + 1):
                    dp_p[j] = dp_p_minus_1[j]
            else:
                c = costs[p - x]
                dp_prev_x = dp[p - x]
                for j in range(1, k + 1):
                    best = dp_p_minus_1[j]
                    prev_val = dp_prev_x[j - 1]
                    if prev_val < INF:
                        cand = prev_val + c
                        if cand < best:
                            best = cand
                    dp_p[j] = best

        return dp[n][k]
